            tensor = self.cast(tensor, dtype=dtype)

        return tensor

    elif isinstance(val, (list, tuple)) and len(val):
        tensors = [self.array(tensor, dtype=dtype) for tensor in val]
        return _torch.stack(tensors)

    return _torch.tensor(val, dtype=dtype)

